const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-96.111167, 29.956182]);
  const roi = point.buffer(4000); // 4km radius

  const date1 = '2013-05-04';
  const date2 = '2016-05-28';

  // 2. Data Acquisition
  // For 2013: Use Landsat 7 or 8 (L8 launched Feb 2013)
  let col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(ee.Date(date1).advance(-7, 'day'), ee.Date(date1).advance(7, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  if (col1.size().getInfo() === 0) {
    // Fallback to Landsat 7
    col1 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(ee.Date(date1).advance(-7, 'day'), ee.Date(date1).advance(7, 'day'))
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
  }

  let col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(ee.Date(date2).advance(-7, 'day'), ee.Date(date2).advance(7, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`2013 Images: ${size1}, 2016 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('No images found for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate MNDWI for water detection
  function addMNDWI(image) {
    // MNDWI = (Green - SWIR1) / (Green + SWIR1)
    const green = image.select('SR_B3').multiply(0.0000275).add(-0.2);
    const swir = image.select('SR_B6').multiply(0.0000275).add(-0.2);
    const mndwi = green.subtract(swir).divide(green.add(swir)).rename('MNDWI');

    // Cloud masking
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return mndwi.updateMask(qaMask);
  }

  const img1 = col1.map(addMNDWI).median().clip(roi);
  const img2 = col2.map(addMNDWI).median().clip(roi);

  // Check for valid pixels
  const count1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  const count2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`Valid pixels - 2013: ${count1}, 2016: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate water area (MNDWI > 0 indicates water)
  const water1 = img1.gt(0);
  const water2 = img2.gt(0);

  const waterArea1 = water1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  const waterArea2 = water2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`Water pixels - 2013: ${waterArea1}, 2016: ${waterArea2}`);

  // 5. Validation & Final Answer
  if (waterArea1 === null || waterArea2 === null || 
      isNaN(waterArea1) || isNaN(waterArea2)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Inundation change: ${waterArea2 - waterArea1} pixels`);

  if (waterArea2 > waterArea1) {
    console.log('Inundation increased in 2016.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Inundation did not increase in 2016.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
